function lruCreate(capacity){ return {cap:capacity, map:new Map()}; }
function lruGet(cache, key){
  if(!cache.map.has(key)) return undefined;
  var v=cache.map.get(key); cache.map.delete(key); cache.map.set(key,v); return v;
}
function lruPut(cache, key, value){
  if(cache.map.has(key)){ cache.map.delete(key); }
  else if(cache.map.size>=cache.cap){ var oldest=cache.map.keys().next().value; cache.map.delete(oldest); }
  cache.map.set(key,value); return cache;
}
function lruKeys(cache){ return Array.from(cache.map.keys()); }
function lruSize(cache){ return cache.map.size; }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { lruCreate:lruCreate, lruGet:lruGet, lruPut:lruPut, lruKeys:lruKeys, lruSize:lruSize };
}
if (typeof window !== 'undefined') {
  window.LruForgePure = { lruCreate:lruCreate, lruGet:lruGet, lruPut:lruPut, lruKeys:lruKeys, lruSize:lruSize };
}
